package com.example.mediqueue.model;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="medical_records") public class MedicalRecord{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@ManyToOne(optional=false) @JoinColumn(name="patient_id") Patient patient;@ManyToOne @JoinColumn(name="doctor_id") Doctor doctor;@Column(length=5000) String notes;@Column(length=2000) String diagnosis;LocalDateTime createdAt=LocalDateTime.now();public MedicalRecord(){}public Long getId(){return id;}public Patient getPatient(){return patient;}public void setPatient(Patient p){patient=p;}public Doctor getDoctor(){return doctor;}public void setDoctor(Doctor d){doctor=d;}public String getNotes(){return notes;}public void setNotes(String n){notes=n;}public String getDiagnosis(){return diagnosis;}public void setDiagnosis(String d){diagnosis=d;}public LocalDateTime getCreatedAt(){return createdAt;}}
